<script setup>import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';import {Head,Link,router} from '@inertiajs/vue3';defineProps({companies:Array,jobs:Array,plans:Array,metrics:Object});const money=v=>new Intl.NumberFormat('en-US',{style:'currency',currency:'USD'}).format(v/100);const remove=j=>confirm(`Delete ${j.title}?`)&&router.delete(route('employer.jobs.destroy',j.id));</script>
<template><Head title="Employer Workspace"/><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><p class="text-xs font-bold uppercase tracking-[.2em] text-[#309689]">Employer</p><h2 class="text-2xl font-bold">Hiring workspace</h2></div><Link :href="route('employer.jobs.create')" class="rounded-lg bg-[#309689] px-4 py-2 font-semibold text-white">Post a job</Link></div></template><div class="mx-auto max-w-7xl space-y-8 px-4 py-10 sm:px-6 lg:px-8"><div v-if="$page.props.flash.success" class="rounded-xl bg-emerald-50 p-4 text-emerald-800">{{$page.props.flash.success}}</div><section class="grid gap-4 sm:grid-cols-2 lg:grid-cols-4"><article v-for="(v,k) in metrics" :key="k" class="rounded-2xl bg-white p-6 shadow-sm"><p class="text-sm capitalize text-gray-500">{{k.replace(/([A-Z])/g,' $1')}}</p><strong class="mt-2 block text-3xl">{{v}}</strong></article></section><section v-if="!companies.length" class="rounded-2xl bg-white p-8 shadow-sm"><h3 class="text-xl font-bold">Create your company</h3><p class="mt-2 text-gray-500">A company profile is required before posting jobs.</p><form class="mt-6 grid gap-4 md:grid-cols-2" @submit.prevent="router.post(route('companies.store'),Object.fromEntries(new FormData($event.target)))"><input name="name" required placeholder="Company name" class="rounded-lg border-gray-300"><input name="email" type="email" placeholder="Business email" class="rounded-lg border-gray-300"><input name="website" placeholder="https://company.com" class="rounded-lg border-gray-300"><input name="industry" placeholder="Industry" class="rounded-lg border-gray-300"><textarea name="description" placeholder="Company description" class="rounded-lg border-gray-300 md:col-span-2"></textarea><button class="rounded-lg bg-[#309689] px-4 py-3 font-semibold text-white">Create company</button></form></section><section v-else class="rounded-2xl bg-white shadow-sm"><div class="flex items-center justify-between border-b p-6"><div><h3 class="text-xl font-bold">Job listings</h3><p class="text-sm text-gray-500">Manage drafts, moderation and applicants.</p></div><Link :href="route('employer.jobs.create')" class="text-sm font-bold text-[#309689]">Create listing</Link></div><div class="overflow-x-auto"><table class="w-full text-left"><thead class="bg-gray-50 text-xs uppercase text-gray-500"><tr><th class="p-4">Job</th><th>Status</th><th>Applications</th><th>Published</th><th class="p-4 text-right">Actions</th></tr></thead><tbody><tr v-for="j in jobs" :key="j.id" class="border-t"><td class="p-4"><b>{{j.title}}</b><small class="block text-gray-500">{{j.company.name}}</small></td><td><span class="rounded-full px-3 py-1 text-xs font-bold" :class="j.status==='published'?'bg-emerald-100 text-emerald-700':j.status==='rejected'?'bg-red-100 text-red-700':'bg-amber-100 text-amber-700'">{{j.status}}</span></td><td>{{j.applications_count}}</td><td>{{j.published_at?new Date(j.published_at).toLocaleDateString():'—'}}</td><td class="space-x-3 p-4 text-right"><Link :href="route('employer.jobs.applicants',j.id)" class="text-sm text-[#309689]">Applicants</Link><Link :href="route('employer.jobs.edit',j.id)" class="text-sm">Edit</Link><button @click="remove(j)" class="text-sm text-red-600">Delete</button></td></tr><tr v-if="!jobs.length"><td colspan="5" class="p-10 text-center text-gray-500">No jobs yet.</td></tr></tbody></table></div></section><section v-if="companies.length" class="grid gap-6 lg:grid-cols-3"><article v-for="company in companies" :key="company.id" class="rounded-2xl bg-[#0e2522] p-6 text-white"><p class="text-sm text-white/60">{{company.verification_status}}</p><h3 class="mt-2 text-xl font-bold">{{company.name}}</h3><p class="mt-3 text-sm text-white/70">{{company.description||'Complete your company profile to attract candidates.'}}</p></article><div class="rounded-2xl bg-white p-6 shadow-sm lg:col-span-2"><h3 class="text-xl font-bold">Dummy subscription plans</h3><div class="mt-5 grid gap-4 sm:grid-cols-3"><div v-for="plan in plans" :key="plan.id" class="rounded-xl border p-4"><b>{{plan.name}}</b><p class="my-2 text-2xl font-bold">{{money(plan.price_cents)}}</p><small>{{plan.job_credits}} job credits</small><button @click="router.post(route('dummy-billing.subscribe',[companies[0].id,plan.id]))" class="mt-4 w-full rounded-lg bg-[#309689] py-2 text-sm font-bold text-white">Activate dummy plan</button></div></div></div></section></div></AuthenticatedLayout></template>
